UPDATE profile_values SET value_json = '[{"degree": "Master of Public Administration", "school": "Troy University", "fieldOfStudy": "", "city": "", "startDate": "", "endDate": "2011"}, {"degree": "Graduate Certificate", "school": "University of South Florida", "fieldOfStudy": "Justice Administration", "city": "", "startDate": "", "endDate": "2016"}, {"degree": "B.S., Business Administration & Management", "school": "University of Phoenix", "fieldOfStudy": "", "city": "", "startDate": "", "endDate": "2007"}, {"degree": "CS coursework", "school": "Troy University", "fieldOfStudy": "programming, business info systems, networking, digital architecture", "city": "", "startDate": "", "endDate": ""}]', updated_at = datetime('now') WHERE user_id='user_ben' AND field_key='st_education';
UPDATE profile_values SET value_json = '[{"name": "SQL", "level": "ADVANCED"}, {"name": "Microsoft Excel", "level": "ADVANCED"}, {"name": "Power BI", "level": "ADVANCED"}, {"name": "Business Reporting", "level": "ADVANCED"}, {"name": "T-SQL", "level": "ADVANCED"}, {"name": "Google Sheets", "level": "ADVANCED"}, {"name": "Microsoft Office", "level": "ADVANCED"}, {"name": "Data Analysis", "level": "ADVANCED"}, {"name": "Data Visualization", "level": "ADVANCED"}, {"name": "Relational Data Modeling", "level": "ADVANCED"}, {"name": "Data Quality / QA", "level": "ADVANCED"}, {"name": "KPI Definition", "level": "ADVANCED"}, {"name": "Python (pandas)", "level": "BEGINNER"}]', updated_at = datetime('now') WHERE user_id='user_ben' AND field_key='st_hardSkills';
UPDATE profile_values SET value_json = json_set((SELECT value_json FROM profile_values WHERE user_id='user_ben' AND field_key='st_workExperiences'), '$[1].description', json_extract('["Residential real estate, $36 million in annual transaction volume. Founded and run the team, managing the full sales cycle from lead generation through closing. Own the data infrastructure across CRM, MLS, transaction management, and bookkeeping systems powering all reporting, forecasting, and decision-making. Analyzed lead conversion data in Excel and CRM to identify metrics predicting closed deals, then rebuilt KPI reporting to focus effort on highest-probability leads. Reconciled data across 4 systems (CRM, MLS, transaction management, bookkeeping) using Excel and SQL to produce one consistent set of numbers for a $36M operation. Built recurring Power BI and Excel reports: agent production, lead conversion, revenue by source, and compliance metrics for leadership and partners. Tracked marketing spend and cost-per-lead in Google Sheets across multiple channels, reallocating budget based on measured ROI per channel."]', '$[0]')), updated_at = datetime('now') WHERE user_id='user_ben' AND field_key='st_workExperiences';
